(2205104, 303498, 3032, '<td valign="top">Finally, an original flower. Good thinking!</td>', 'Finally, an original flower. Good thinking!', '2006-03-06 17:23:31.000000', NULL, 1),
(2205108, 302418, 40019, '<td valign="top">Great image.  "Just" a little over sharpened for my liking.  The pixelization around the nose is distracting. Very nice picture though. Would have benefited from being just a little bit softer (IMO).</td>', 'Great image.  "Just" a little over sharpened for my liking.  The pixelization around the nose is distracting. Very nice picture though. Would have benefited from being just a little bit softer (IMO).', '2006-03-06 17:25:07.000000', NULL, 1),
