(2213751, 303506, 12611, '<td valign="top">If you had a square white japanese bowl it might win a ribbon; its a great shot; excellent vivd cream and strawberries; I think I''ll go have breakfast! good luck!</td>', 'If you had a square white japanese bowl it might win a ribbon; its a great shot; excellent vivd cream and strawberries; I think I''ll go have breakfast! good luck!', '2006-03-09 07:44:29.000000', NULL, 1),
(2213752, 303540, 31708, '<td valign="top">nice color</td>', 'nice color', '2006-03-09 07:44:47.000000', NULL, 1),
(2213753, 302864, 31708, '<td valign="top">looks like the color could be a little brigher,JMO</td>', 'looks like the color could be a little brigher,JMO', '2006-03-09 07:45:44.000000', NULL, 1),
(2213759, 302635, 31708, '<td valign="top">JMO,  there is alot of space, I think I personally would have liked it better zoomed in tighter on the flowers. Again, JMO</td>', 'JMO,  there is alot of space, I think I personally would have liked it better zoomed in tighter on the flowers. Again, JMO', '2006-03-09 07:47:29.000000', NULL, 1),
(2213761, 303607, 12611, '<td valign="top">vertigo inducing, really. this shotshould come with a referal to a vestibular disorders clinic. But, its got great shapes and "negative" sky space.</td>', 'vertigo inducing, really. this shotshould come with a referal to a vestibular disorders clinic. But, its got great shapes and "negative" sky space.', '2006-03-09 07:47:35.000000', NULL, 1),
