(2216104, 303498, 51802, '<td valign="top">Very clever idea.</td>', 'Very clever idea.', '2006-03-09 23:45:21.000000', NULL, 1),
(2216119, 302558, 11843, '<td valign="top">This would be really nice if it wasn''t for the softbox highlights being directly in her pupils. Its very distracting. 6</td>', 'This would be really nice if it wasn''t for the softbox highlights being directly in her pupils. Its very distracting. 6', '2006-03-09 23:54:24.000000', NULL, 1),
