INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2222424, 303091, 41337, '<td valign="top">Good news is I''m bumping this since it''s one of my favorites in the challenge. I love the pose/composition. The bad news is my favorites never win ribbons. Hopefully this won''t be the kiss of death for you. :)</td>', 'Good news is I''m bumping this since it''s one of my favorites in the challenge. I love the pose/composition. The bad news is my favorites never win ribbons. Hopefully this won''t be the kiss of death for you. :)', '2006-03-12 17:38:06.000000', NULL, 1),
(2222425, 302558, 38706, '<td valign="top">Great composition and I like the crop a lot.  I think it would be better without the red in the whites but that square catch light does not work for me, at least where they are (maybe in the whites, it would work).</td>', 'Great composition and I like the crop a lot.  I think it would be better without the red in the whites but that square catch light does not work for me, at least where they are (maybe in the whites, it would work).', '2006-03-12 17:39:13.000000', NULL, 1),
(2222478, 302618, 14620, '<td valign="top">One of my absolute favorites of the challenge.  The subdued colors of everything except the child just draws the eye right to him.  I enjoy photos like this the most, just wonderful moments captured in time, photos that just spill over with some sort of emotion.  In this case, the sheer joy of an innocent child.  Perfect crop! bumping to a 10</td>', 'One of my absolute favorites of the challenge.  The subdued colors of everything except the child just draws the eye right to him.  I enjoy photos like this the most, just wonderful moments captured in time, photos that just spill over with some sort of emotion.  In this case, the sheer joy of an innocent child.  Perfect crop! bumping to a 10', '2006-03-12 18:24:27.000000', NULL, 1),
(2222490, 303589, 2158, '<td valign="top">You certainly waited for the perfect moment.  The sun makes this picture work so much better.</td>', 'You certainly waited for the perfect moment.  The sun makes this picture work so much better.', '2006-03-12 18:34:28.000000', NULL, 1),
(2222501, 303270, 16912, '<td valign="top">Very clean and crisp shot, lighting is great and the composition complex yet simple. I have high hopes for this - as I''m sure you do ;) (bumping up 1)</td>', 'Very clean and crisp shot, lighting is great and the composition complex yet simple. I have high hopes for this - as I''m sure you do ;) (bumping up 1)', '2006-03-12 18:46:27.000000', NULL, 1),
(2222524, 303267, 40484, '<td valign="top">Good caputure of the gull. I think it may have been better if you had been able to crop it so that the gull was flying into the picture instead of out of it (JMO).</td>', 'Good caputure of the gull. I think it may have been better if you had been able to crop it so that the gull was flying into the picture instead of out of it (JMO).', '2006-03-12 19:16:07.000000', NULL, 1),
