(2222546, 303445, 33361, '<td valign="top">very nice - just wish the tendrel in the center of her face was more to the side.</td>', 'very nice - just wish the tendrel in the center of her face was more to the side.', '2006-03-12 19:30:07.000000', NULL, 1),
(2222552, 301028, 33361, '<td valign="top">I prefer more off-center</td>', 'I prefer more off-center', '2006-03-12 19:31:42.000000', NULL, 1),
(2222553, 303335, 33361, '<td valign="top">cute! 8</td>', 'cute! 8', '2006-03-12 19:32:09.000000', NULL, 1),
